package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import jakarta.validation.constraints.*;
import jakarta.validation.Valid;
import java.math.BigDecimal;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Financial mapping does not change physical inventory, work evidence, or past movement dimensions. */
@Service @Transactional
public class FinanceSupplyDimensionService {
 public record Item(@NotNull UUID requestId,@NotNull UUID itemId,@Min(0) long expectedVersion,@NotBlank @Size(max=80) String financialCategoryCode,UUID recommendedDepartmentId,@NotBlank @Size(max=2000) String note){}
 public record Classification(@NotNull UUID requestId,@NotNull UUID movementId,@NotBlank @Size(max=80) String financialCategoryCode,@NotNull UUID actualDepartmentId,@NotBlank @Size(max=2000) String note,@Pattern(regexp="NONE|CONTRACT|CIP") String projectKind,UUID projectId){public Classification(UUID requestId,UUID movementId,String code,UUID department,String note){this(requestId,movementId,code,department,note,null,null);}}
 public record ProcurementClassification(@NotNull UUID requestId,@NotNull UUID lineId,@NotBlank @Size(max=80) String financialCategoryCode,@NotNull UUID actualDepartmentId,@NotBlank @Size(max=2000) String note,@Pattern(regexp="NONE|CONTRACT|CIP") String projectKind,UUID projectId){public ProcurementClassification(UUID requestId,UUID lineId,String code,UUID department,String note){this(requestId,lineId,code,department,note,null,null);}}
 public record CostShare(@NotNull UUID departmentId,@NotBlank @Size(max=80) String financialCategoryCode,@NotNull @DecimalMin("0.01") @Digits(integer=16,fraction=2) BigDecimal amount,@Pattern(regexp="NONE|CONTRACT|CIP") String projectKind,UUID projectId){public CostShare(UUID department,String code,BigDecimal amount){this(department,code,amount,null,null);}}
 public record PriceCosts(@NotNull UUID requestId,@NotNull UUID sourceEventId,@NotEmpty @Size(max=100) List<@Valid CostShare> allocations,@NotBlank @Size(max=2000) String note){}
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final AuditWriter audit;
 public FinanceSupplyDimensionService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,AuditWriter audit){this.jdbc=jdbc;this.database=database;this.access=access;this.audit=audit;}
 public Map<String,Object> context(UUID hotel){
  var p=prepare("finance.read","finance.accounting.read");access.requireOrgScope(hotel);var b=base(p).addValue("hotel",hotel);var result=new LinkedHashMap<String,Object>();
  result.put("categories",FinanceCostDimensions.categories(jdbc,p.tenantId(),hotel));result.put("departments",FinanceCostDimensions.departments(jdbc,p.tenantId(),hotel));
  result.put("items",jdbc.queryForList("select id,name,sku,row_version,financial_category_code,financial_department_id from store_resource_item where tenant_id=:tenant and hotel_org_unit_id=:hotel and status='ACTIVE' order by name",b));
  result.put("pendingMovements",jdbc.queryForList("select m.id,i.name,m.source_type,m.source_id,m.value_delta,m.occurred_at,m.financial_category_code,m.financial_department_id,m.actor_account_id,e.book_amount,to_jsonb(m)->>'project_kind' project_kind,to_jsonb(m)->>'project_id' project_id from store_inventory_movement m join store_resource_item i on i.tenant_id=m.tenant_id and i.id=m.item_id left join fs_inventory_event e on e.tenant_id=m.tenant_id and e.movement_id=m.id where m.tenant_id=:tenant and m.hotel_org_unit_id=:hotel and m.source_type not in ('PROCUREMENT','PROCUREMENT_RETURN') and m.value_delta<>0 and (m.financial_category_code is null or m.financial_department_id is null or coalesce(to_jsonb(m)->>'project_kind','NONE')='NONE' and not exists(select 1 from fbu_flow f where f.tenant_id=m.tenant_id and f.source_kind='INVENTORY' and f.source_id=m.id)) and not exists(select 1 from fs_movement_finance_classification c where c.tenant_id=m.tenant_id and c.movement_id=m.id) order by m.occurred_at,m.id limit 500",b));
  result.put("pendingProcurementLines",jdbc.queryForList("select l.id,l.order_id,l.item_name,l.line_kind,l.quantity,l.unit_price,l.financial_category_code,l.financial_department_id,to_jsonb(l)->>'project_kind' project_kind,to_jsonb(l)->>'project_id' project_id,o.title,o.status from procurement_line l join procurement_order o on o.tenant_id=l.tenant_id and o.id=l.order_id where l.tenant_id=:tenant and l.hotel_id=:hotel and o.status not in ('DRAFT','RETURNED') and (l.financial_category_code is null or l.financial_department_id is null) and not exists(select 1 from fs_procurement_finance_classification c where c.tenant_id=l.tenant_id and c.line_id=l.id) order by o.created_at,l.id limit 500",b));
  result.put("pendingPriceCosts",jdbc.queryForList("select e.id,e.source_id,e.event_key,e.accounting_date,e.amount,e.metadata from fa_source_event e where e.tenant_id=:tenant and e.hotel_id=:hotel and e.source_type='FS_PROCUREMENT' and e.metadata->>'nature'='CONSUMED_PRICE_ADJUSTMENT' and not exists(select 1 from fs_price_cost_allocation c where c.tenant_id=e.tenant_id and c.source_event_id=e.id) order by e.accounting_date,e.id limit 500",b));
  result.put("budgetFlows",jdbc.queryForList("select f.*,o.title document_title from fbu_flow f left join procurement_order o on o.tenant_id=f.tenant_id and o.id=f.document_id where f.tenant_id=:tenant and f.hotel_id=:hotel order by f.month desc,f.created_at desc limit 500",b));
  result.put("budgetIssues",jdbc.queryForList("select i.* from fbu_issue i where i.tenant_id=:tenant and i.hotel_id=:hotel and i.status='OPEN' and (i.source_kind<>'PROJECT_HISTORY' or exists(select 1 from fc_policy p where p.tenant_id=i.tenant_id and p.id=i.source_id and p.hotel_id=i.hotel_id and p.kind='BUDGET' and p.status='PUBLISHED' and coalesce(p.spec->>'projectKind','ALL') in ('CONTRACT','CIP'))) order by i.created_at,i.source_id limit 500",b));
  result.put("notice","物品默认部门只是建议，不是实际领用部门证据。已批准历史采购和缺维度消耗须独立财务按原件追加归类。库存资金基数是累计已确认购入减退货，不是现存库存价值，也不是费用实际；费用以真实领用/服务受益为准。");return output(result);
 }
 public Map<String,Object> item(Item in){var p=prepare("finance.configure");var b=base(p).addValue("id",in.itemId());var item=one("select * from store_resource_item where tenant_id=:tenant and id=:id for update",b);UUID hotel=id(item.get("hotel_org_unit_id"));access.requireOrgScope(hotel);UUID department=in.recommendedDepartmentId()==null?hotel:in.recommendedDepartmentId();var category=FinanceCostDimensions.validate(jdbc,p.tenantId(),hotel,in.financialCategoryCode(),department,Set.of("EXPENSE"));if(((Number)item.get("row_version")).longValue()!=in.expectedVersion())throw conflict("物品版本已变化，请重新核对财务映射");jdbc.update("update store_resource_item set financial_category_code=:code,financial_department_id=:department,row_version=row_version+1 where tenant_id=:tenant and id=:id",b.addValue("code",in.financialCategoryCode()).addValue("department",in.recommendedDepartmentId()));audit.record("FINANCE_ITEM_DIMENSION_CONFIGURED","STORE_ITEM",in.itemId(),json(Map.of("requestId",in.requestId(),"previous",output(item),"categoryPolicy",output(category),"recommendationOnly",true,"note",in.note())));return output(one("select * from store_resource_item where tenant_id=:tenant and id=:id",b));}
 public Map<String,Object> classify(Classification in){var p=prepare("finance.review");access.requireAnyPermission("finance.read","finance.accounting.read");var b=base(p).addValue("id",in.movementId());var movement=one("select * from store_inventory_movement where tenant_id=:tenant and id=:id",b);UUID hotel=id(movement.get("hotel_org_unit_id"));access.requireOrgScope(hotel);if(p.actorId().equals(movement.get("actor_account_id")))throw conflict("实际部门人工归类须由非原库存登记人的独立财务核对");if(Set.of("PROCUREMENT","PROCUREMENT_RETURN").contains(movement.get("source_type")))throw conflict("采购入退库不伪装领用费用归类，应承接原采购明示类别");if(movement.get("financial_category_code")!=null&&movement.get("financial_department_id")!=null&&!newProjectBeforeCapture(p,movement,in.projectKind(),in.projectId()))throw conflict("原流水已冻结真实部门与类别，不能覆盖历史维度");if(movement.get("financial_category_code")!=null&&!in.financialCategoryCode().equals(movement.get("financial_category_code"))||movement.get("financial_department_id")!=null&&!in.actualDepartmentId().equals(movement.get("financial_department_id")))throw conflict("不能以追加归类覆盖原流水已冻结的明确类别/实际部门");var project=classificationProject(p,hotel,movement,in.projectKind(),in.projectId());var category=FinanceCostDimensions.validate(jdbc,p.tenantId(),hotel,in.financialCategoryCode(),in.actualDepartmentId(),Set.of("EXPENSE"));if(jdbc.queryForObject("select count(*) from fa_book k join fa_period q on q.tenant_id=k.tenant_id and q.book_id=k.id where k.tenant_id=:tenant and k.hotel_id=:hotel and q.month=date_trunc('month',cast(:occurred as timestamptz) at time zone (select timezone from tenant where id=:tenant))::date and q.status='CLOSED'",b.addValue("hotel",hotel).addValue("occurred",movement.get("occurred_at")),Long.class)>0)throw conflict("原成本月份已关账，不能追加归类改写旧期；需在开放期做真实重分类调整");var prior=jdbc.queryForList("select * from fs_movement_finance_classification where tenant_id=:tenant and movement_id=:id",b);if(!prior.isEmpty()){var row=prior.getFirst();if(!in.financialCategoryCode().equals(row.get("financial_category_code"))||!in.actualDepartmentId().equals(row.get("financial_department_id"))||!in.note().equals(row.get("note"))||!sameProject(row,project))throw conflict("原流水已有不同不可变人工归类，不能静默覆盖");new FinanceAuxiliaryDimensions(jdbc).completeMovement(p,in.movementId());return output(row);}jdbc.update("insert into fs_movement_finance_classification(movement_id,tenant_id,hotel_id,financial_category_code,financial_department_id,actor_id,note,source_snapshot"+projectColumns()+") values(:id,:tenant,:hotel,:code,:department,:actor,:note,cast(:snapshot as jsonb)"+projectValues()+")",projectParameters(b,project).addValue("code",in.financialCategoryCode()).addValue("department",in.actualDepartmentId()).addValue("note",in.note()).addValue("snapshot",json(Map.of("movement",output(movement),"publishedCategory",output(category),"requestId",in.requestId(),"actualDepartmentExplicitlyConfirmed",true))));if(jdbc.queryForObject("select count(*) from fs_inventory_event where tenant_id=:tenant and movement_id=:id",b,Long.class)>0)new FinanceBudgetBridge(jdbc).inventory(p,in.movementId());new FinanceAuxiliaryDimensions(jdbc).completeMovement(p,in.movementId());audit.record("FINANCE_MOVEMENT_ACTUAL_DEPARTMENT_CONFIRMED","STORE_MOVEMENT",in.movementId(),json(in));return output(one("select * from fs_movement_finance_classification where tenant_id=:tenant and movement_id=:id",b));}
 private TenantPrincipal prepare(String...permissions){access.requireAnyPermission(permissions);var p=access.principal();database.apply(p.tenantId());return p;}
 public Map<String,Object> priceCosts(PriceCosts in){
  var p=prepare("finance.review");access.requireAnyPermission("finance.read","finance.accounting.read");var b=base(p).addValue("id",in.sourceEventId());
  var event=one("select e.*,f.applicant_id from fa_source_event e join fs_recognition f on f.tenant_id=e.tenant_id and f.id=e.source_id where e.tenant_id=:tenant and e.id=:id and e.source_type='FS_PROCUREMENT' and e.metadata->>'nature'='CONSUMED_PRICE_ADJUSTMENT' for update of f",b);
  UUID hotel=id(event.get("hotel_id"));access.requireOrgScope(hotel);if(p.actorId().equals(event.get("applicant_id")))throw conflict("已耗用价差实际受益部门须由非原申请人的独立财务核实");
  if(jdbc.queryForObject("select count(*) from fa_period p join fa_book k on k.tenant_id=p.tenant_id and k.id=p.book_id where p.tenant_id=:tenant and k.hotel_id=:hotel and p.month=date_trunc('month',cast(:date as date))::date and p.status='CLOSED'",b.addValue("hotel",hotel).addValue("date",event.get("accounting_date")),Long.class)>0)throw conflict("价差原期已关账，不静默补写成本部门；须开放期受控重分类");
  BigDecimal total=BigDecimal.ZERO;var departments=new HashSet<String>();for(var share:in.allocations()){if(share.amount().signum()<=0||share.amount().scale()>2)throw bad("价差分配必须为精确到分的正数");if(!departments.add(share.departmentId()+":"+Objects.toString(share.projectKind(),"NONE")+":"+share.projectId()))throw bad("同一实际部门不可重复，须明确合并本次价差归集");FinanceCostDimensions.validate(jdbc,p.tenantId(),hotel,share.financialCategoryCode(),share.departmentId(),Set.of("EXPENSE"));total=total.add(share.amount());}
  if(total.compareTo(amount(event.get("amount")))!=0)throw conflict("实际部门价差分配须与原会计来源精确相等，不得造差额或重复费用");
  var prior=jdbc.queryForList("select * from fs_price_cost_allocation where tenant_id=:tenant and source_event_id=:id",b);if(!prior.isEmpty()){if(!sameCostShares(in.allocations(),rows(prior.getFirst().get("allocations")))||!in.note().equals(prior.getFirst().get("note")))throw conflict("原耗用价差已有不同冻结分配，不覆盖历史");new FinanceAuxiliaryDimensions(jdbc).completePriceCosts(p,in.sourceEventId());return output(prior.getFirst());}
  jdbc.update("insert into fs_price_cost_allocation(source_event_id,tenant_id,hotel_id,actor_id,allocations,note,source_snapshot) values(:id,:tenant,:hotel,:actor,cast(:allocations as jsonb),:note,cast(:snapshot as jsonb))",b.addValue("allocations",json(freezeShares(p,hotel,in.allocations()))).addValue("note",in.note()).addValue("snapshot",json(Map.of("sourceEvent",output(event),"requestId",in.requestId(),"actualDepartmentsExplicitlyConfirmed",true))));
  new FinanceBudgetBridge(jdbc).priceAdjustment(p,in.sourceEventId());new FinanceAuxiliaryDimensions(jdbc).completePriceCosts(p,in.sourceEventId());audit.record("FINANCE_CONSUMED_PRICE_COST_ALLOCATED","FA_SOURCE_EVENT",in.sourceEventId(),json(in));return output(one("select * from fs_price_cost_allocation where tenant_id=:tenant and source_event_id=:id",b));
 }
 public Map<String,Object> procurementLine(ProcurementClassification in){
  var p=prepare("finance.review");access.requireAnyPermission("finance.read","finance.accounting.read");
  var b=base(p).addValue("id",in.lineId());var line=one("select l.*,o.applicant_id,o.buyer_id,o.status order_status,o.created_at order_created_at from procurement_line l join procurement_order o on o.tenant_id=l.tenant_id and o.id=l.order_id where l.tenant_id=:tenant and l.id=:id for update of o",b);
  UUID hotel=id(line.get("hotel_id"));access.requireOrgScope(hotel);
  if(p.actorId().equals(line.get("applicant_id"))||p.actorId().equals(line.get("buyer_id")))throw conflict("历史采购归类须由非原申请/采购经办人的独立财务核对");
  if(Set.of("DRAFT","RETURNED").contains(line.get("order_status")))throw conflict("未批准采购应在原申请中明确类别，不能以历史归类绕过原审批");
  if(line.get("financial_category_code")!=null&&!in.financialCategoryCode().equals(line.get("financial_category_code"))||line.get("financial_department_id")!=null&&!in.actualDepartmentId().equals(line.get("financial_department_id")))throw conflict("不能覆盖原采购已明确冻结的成本类别/部门");
  if(line.get("financial_category_code")!=null&&line.get("financial_department_id")!=null)throw conflict("原采购已经明确归类，不得重写");
  Set<String> treatments=switch(Objects.toString(line.get("line_kind"))){case "SERVICE"->Set.of("EXPENSE");case "ASSET","PROJECT"->Set.of("ASSET");default->Set.of("EXPENSE","INVENTORY");};
  var project=classificationProject(p,hotel,line,in.projectKind(),in.projectId());var category=FinanceCostDimensions.validate(jdbc,p.tenantId(),hotel,in.financialCategoryCode(),in.actualDepartmentId(),treatments);
  if(jdbc.queryForObject("select count(*) from fa_period q join fa_book k on k.tenant_id=q.tenant_id and k.id=q.book_id where q.tenant_id=:tenant and k.hotel_id=:hotel and q.status='CLOSED' and (q.month=date_trunc('month',cast(:created as timestamptz) at time zone (select timezone from tenant where id=:tenant))::date or exists(select 1 from procurement_receipt_line rl join fs_recognition f on f.tenant_id=rl.tenant_id and f.receipt_id=rl.receipt_id where rl.tenant_id=:tenant and rl.line_id=:id and date_trunc('month',f.accounting_date)::date=q.month))",b.addValue("hotel",hotel).addValue("created",line.get("order_created_at")),Long.class)>0)throw conflict("历史采购涉及已关账月份，不能静默追加改变旧期成本维度；须开放期受控重分类");
  var existing=jdbc.queryForList("select * from fs_procurement_finance_classification where tenant_id=:tenant and line_id=:id",b);
  if(!existing.isEmpty()){var previous=existing.getFirst();if(!in.financialCategoryCode().equals(previous.get("financial_category_code"))||!in.actualDepartmentId().equals(previous.get("financial_department_id"))||!in.note().equals(previous.get("note"))||!sameProject(previous,project))throw conflict("历史原行已有不同不可变归类，不覆盖历史");return output(previous);}
  jdbc.update("insert into fs_procurement_finance_classification(line_id,tenant_id,hotel_id,order_id,financial_category_code,financial_department_id,actor_id,note,source_snapshot"+projectColumns()+") values(:id,:tenant,:hotel,:order,:code,:department,:actor,:note,cast(:snapshot as jsonb)"+projectValues()+")",projectParameters(b,project).addValue("order",line.get("order_id")).addValue("code",in.financialCategoryCode()).addValue("department",in.actualDepartmentId()).addValue("note",in.note()).addValue("snapshot",json(Map.of("originalLine",output(line),"publishedCategory",output(category),"requestId",in.requestId(),"independentlyConfirmed",true))));
  var bridge=new FinanceBudgetBridge(jdbc);bridge.procurement(p,id(line.get("order_id")),"SUBMITTED".equals(line.get("order_status"))?"SUBMIT":"APPROVE");
  for(var recognition:jdbc.queryForList("select distinct f.id from procurement_receipt_line rl join fs_recognition f on f.tenant_id=rl.tenant_id and f.receipt_id=rl.receipt_id where rl.tenant_id=:tenant and rl.line_id=:id and f.status in ('CONFIRMED','ESTIMATED')",b))bridge.recognition(p,id(recognition.get("id")));
  for(var returned:jdbc.queryForList("select id from fs_return where tenant_id=:tenant and line_id=:id and status='APPROVED'",b))bridge.returnReviewed(p,id(returned.get("id")));
  audit.record("FINANCE_HISTORICAL_PROCUREMENT_CLASSIFIED","PROCUREMENT_LINE",in.lineId(),json(in));
  return output(one("select * from fs_procurement_finance_classification where tenant_id=:tenant and line_id=:id",b));
 }

 private boolean newProjectBeforeCapture(TenantPrincipal p,Map<String,Object> original,String kind,UUID reference){if(!FinanceCostDimensions.projectsInstalled(jdbc)||kind==null||kind.equals("NONE")||reference==null||!Objects.toString(original.get("project_kind"),"NONE").equals("NONE"))return false;var b=base(p).addValue("movement",original.get("id")).addValue("project",kind+":"+reference);return jdbc.queryForObject("select count(*) from fbu_flow where tenant_id=:tenant and source_kind='INVENTORY' and source_id=:movement",b,Long.class)==0||jdbc.queryForObject("select count(*) from fs_movement_finance_classification where tenant_id=:tenant and movement_id=:movement and project_key=:project",b,Long.class)==1;}
 private Map<String,Object> classificationProject(TenantPrincipal p,UUID hotel,Map<String,Object> original,String kind,UUID reference){String existing=Objects.toString(original.get("project_kind"),"NONE");if(!existing.equals("NONE")){if(kind!=null&&(!kind.equals(existing)||!Objects.equals(reference,id(original.get("project_id")))))throw conflict("不能通过成本归类覆盖原来源已冻结真实项目");return map(original.get("project_snapshot"));}return FinanceCostDimensions.freezeProject(jdbc,p,hotel,kind,reference);}
 private boolean sameProject(Map<String,Object> stored,Map<String,Object> wanted){return Objects.toString(stored.get("project_key"),"NONE").equals(Objects.toString(wanted.get("key"),"NONE"));}
 private String projectColumns(){return FinanceCostDimensions.projectsInstalled(jdbc)?",project_kind,project_id,project_key,project_snapshot":"";}
 private String projectValues(){return FinanceCostDimensions.projectsInstalled(jdbc)?",:projectKind,:projectId,:projectKey,cast(:projectSnapshot as jsonb)":"";}
 private MapSqlParameterSource projectParameters(MapSqlParameterSource b,Map<String,Object> project){return b.addValue("projectKind",project.get("kind")).addValue("projectId",id(project.get("id"))).addValue("projectKey",project.get("key")).addValue("projectSnapshot",json(project));}
 private List<Map<String,Object>> freezeShares(TenantPrincipal p,UUID hotel,List<CostShare> shares){var result=new ArrayList<Map<String,Object>>();for(var share:shares){var project=FinanceCostDimensions.freezeProject(jdbc,p,hotel,share.projectKind(),share.projectId());var row=new LinkedHashMap<String,Object>();row.put("departmentId",share.departmentId().toString());row.put("financialCategoryCode",share.financialCategoryCode());row.put("amount",share.amount().toPlainString());row.put("projectKind",project.get("kind"));row.put("projectId",project.get("id"));row.put("projectSnapshot",project);result.add(row);}return result;}
 private boolean sameCostShares(List<CostShare> expected,List<Map<String,Object>> actual){if(expected.size()!=actual.size())return false;for(int i=0;i<expected.size();i++){var e=expected.get(i);var a=actual.get(i);if(!e.departmentId().equals(id(a.get("departmentId")))||!e.financialCategoryCode().equals(a.get("financialCategoryCode"))||e.amount().compareTo(amount(a.get("amount")))!=0||!Objects.toString(e.projectKind(),"NONE").equals(Objects.toString(a.get("projectKind"),"NONE"))||!Objects.equals(e.projectId(),id(a.get("projectId"))))return false;}return true;}
 private Map<String,Object> one(String sql,MapSqlParameterSource b){var r=jdbc.queryForList(sql,b);if(r.isEmpty())throw missing();return r.getFirst();}
}
